!function(m){function a(a){for(var i,r,e=a[0],n=a[1],g=a[2],_=0,o=[];_<e.length;_++)r=e[_],Object.prototype.hasOwnProperty.call(s,r)&&s[r]&&o.push(s[r][0]),s[r]=0;for(i in n)Object.prototype.hasOwnProperty.call(n,i)&&(m[i]=n[i]);for(u&&u(a);o.length;)o.shift()();return p.push.apply(p,g||[]),t()}function t(){for(var m,a=0;a<p.length;a++){for(var t,r=p[a],e=!0,n=1;n<r.length;n++)t=r[n],0!==s[t]&&(e=!1);e&&(p.splice(a--,1),m=i(i.s=r[0]))}return m}function i(a){if(r[a])return r[a].exports;var t=r[a]={i:a,l:!1,exports:{}};return m[a].call(t.exports,t,t.exports,i),t.l=!0,t.exports}var r={},s={44:0},p=[];i.m=m,i.c=r,i.d=function(m,a,t){i.o(m,a)||Object.defineProperty(m,a,{enumerable:!0,get:t})},i.r=function(m){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(m,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(m,"__esModule",{value:!0})},i.t=function(m,a){if(1&a&&(m=i(m)),8&a)return m;if(4&a&&"object"==typeof m&&m&&m.__esModule)return m;var t=Object.create(null);if(i.r(t),Object.defineProperty(t,"default",{enumerable:!0,value:m}),2&a&&"string"!=typeof m)for(var r in m)i.d(t,r,function(a){return m[a]}.bind(null,r));return t},i.n=function(m){var a=m&&m.__esModule?function(){return m.default}:function(){return m};return i.d(a,"a",a),a},i.o=function(m,a){return Object.prototype.hasOwnProperty.call(m,a)},i.p="";var e=window.webpackJsonp=window.webpackJsonp||[],n=e.push.bind(e);e.push=a,e=e.slice();for(var g=0;g<e.length;g++)a(e[g]);var u=n;p.push([25,0]),t()}({25:function(m,a,t){"use strict";t.r(a);var i=t(0);Object(i.a)("us","army",t(26),t(1))},26:function(m){m.exports=JSON.parse('{"category":[{"name":"美国","link":"us_shortcut"},{"name":"陆战武器","link":"us_army"},{"name":"坦克","link":"us_army#us_army_tank"}],"model":"M4中型坦克","description":"<h6>综述：</h6><p>1940年，美国在M3中型坦克的基础上开始研制M4中型坦克，它沿用了M3中型坦克的底盘、悬挂装置、传动装置和发动机等部件，对M3火力不足、装甲薄弱和炮塔转速太慢等缺陷作了提升和改进，于1941年9月定型并量产。此后，一共有十多家制造厂生产M4各型坦克，二战期间共生产了49234辆，并装备给各国盟军，由此M4中型坦克身影遍布二战各个战场。M4中型坦克一共有M4、M4A1、M4A2、M4A3、M4A4、M4A6等多种型号（M4A5为加拿大生产的“公羊”Ram Ⅱ型坦克），英军将M4中型坦克以“谢尔曼”命名（“谢尔曼”是美国南北战争中的一位北军将领名字），并以坦克火炮的类型给M4分为：“谢尔曼”-75mm口径炮，“谢尔曼”A-76mm口径炮，“谢尔曼”B-105mm口径炮，“谢尔曼”C-可发射17磅重弹药的炮。</p><p>注：（关于M4各型坦克的生产数量 ，由于统计的截止时间不一，各资料所述的生产数量会有不同，故以下凡涉及产量的数字只供参考。）</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"{{text}}M4“谢尔曼Ⅰ”中型坦克{{image}}imgs/us/army/us_army_tankm4_11.jpg{{text}}1945年1月，德国布拉赫伦地区，美第9军第701坦克营A连的M4“谢尔曼Ⅰ型”中型坦克。{{image}}imgs/us/army/us_army_tankm4_12.jpg{{text}}1944年7月，法国诺曼第地区，美军第4装甲师第8坦克营的M4（105）中型坦克。该型坦克改装了105mmM4榴弹炮，开始服役时间是1944年2月。{{image}}imgs/us/army/us_army_tankm4_13.jpg","description":"<h6>M4“谢尔曼Ⅰ型”中型坦克</h6><p>该型坦克是焊接车体，坦克新装了二战时唯一的火炮垂直稳定器，能够在行进中瞄准射击；坦克的炮塔转速也提高至10秒转一周，也是二战中坦克中最快的；此外它还具有较好的机动性能，所装备的500匹马力汽油发动机也是二战坦克中最优秀的；M4坦克车体正面装甲厚度只有50mm，但其70度倾斜角的结构使它的抗弹能力得到提高（相当于70mm厚装甲）；早期的M4装备的 75mm53倍身管的火炮，虽然该炮在1000m距离上穿甲能力已达到近90mm，但火力仍然比不上德军的“豹”式和“虎”式坦克。</p><p>坦克参数：车长：5.89m，车宽：2.62m，车高：2.74m，车重：约30t，乘员5人；最大车速：39km/h，最大行程：193km；装甲厚度：13-88mm；武器装备：一门75mmM3火炮，2挺机枪（7.62mm和12.7mm），炮塔中还备1门50.8mm口径的迫击炮。</p><p>M4中型坦克在1942年7月开始服役，一共生产了670辆装备75mm火炮的M4和1640辆装备105mm火炮的M4（105）。</p><span class=\'custom-document-caption text-secondary\'><strong>外形特点：</strong><ol><li>悬挂系统两侧各有6个负重轮（2个一对，共3对）。</li><li>单炮塔，火炮有较大的防护炮盾。</li><li>车体较高，车体正前方装甲有较大倾角。</li></ol></span>","caption":""},{"image":"{{text}}M4A1“谢尔曼Ⅱ”中型坦克{{image}}imgs/us/army/us_army_tankm4_21.jpg{{text}}1943年1月，意大利西西里岛，美军第2装甲师的一辆M4A1中型坦克。{{image}}imgs/us/army/us_army_tankm4_22.jpg{{text}}1945年4月，隶属美军第2装甲师第41坦克团的一辆M4A1W(76)中型坦克。注意：装备76mm火炮的炮塔后部有一突出部分，这是与装备75mm火炮的坦克不同处。{{image}}imgs/us/army/us_army_tankm4_23.jpg","description":"<h6>M4A1“谢尔曼Ⅱ”中型坦克</h6><p>该型坦克是浇铸车体，其它的结构、性能与M4基本相同。</p><p>二战期间， 一共生产了6200多辆装备75mm火炮的M4A1和3420辆装备76mm火炮的M4A1（76）中型坦克。</p><p>M4A1中型坦克在1942年2月开始服役。</p>","caption":""},{"image":"{{text}}M4A2“谢尔曼Ⅲ”中型坦克{{image}}imgs/us/army/us_army_tankm4_31.jpg{{text}}1943年11月，美国海军陆战队某坦克团C连的一辆M4A2中型坦克。{{image}}imgs/us/army/us_army_tankm4_32.jpg{{text}}1944年7月，太平洋关岛，美国海军陆战队第2独立坦克连的一辆M4A2中型坦克。{{image}}imgs/us/army/us_army_tankm4_33.jpg","description":"<h6>M4A2“谢尔曼Ⅲ”中型坦克</h6><p>该型车结构、性能与M4基本相同，坦克仍装备75mm口径火炮（后期；但车体部份构件已从铸件改为焊接件，且焊接构件的棱角尖锐（与M4和M4A3的明显区别处）。后期的M4A2中型坦克的一个重要改进是其炮塔顶部增加了一个装填手的出入舱门，实战表明：早期的M4中型坦克由于炮塔顶部只有一个车长舱门，当坦克被击中起火时，装填手只能等到车长和炮手逃出后才能出舱，造成逃生时间不足而导致伤亡；增加此舱门后，大大增加了坦克车组人员（特别是装填手）的逃生安全机率。</p><p>M4A2中型坦克在1942年4月正式服役。二战期间生产了8050辆装备75mm火炮的M4A2和2900多辆装备76mm火炮的M4A2（76）中型坦克。</p>","caption":""},{"image":"{{text}}M4A3“谢尔曼Ⅳ”中型坦克{{image}}imgs/us/army/us_army_tankm4_41.jpg{{text}}1944年7月，在法国诺曼第地区，美军第4装甲师的一辆M4A3(76)中型坦克。{{image}}imgs/us/army/us_army_tankm4_42.jpg{{text}}1945年3月，在德国战场，美军第12装甲师714坦克团“H”连第2排的一辆M4A3中型坦克。{{image}}imgs/us/army/us_army_tankm4_43.jpg","description":"<h6>M4A3“谢尔曼Ⅳ”中型坦克</h6><p>该型车坦克为焊接车体，车体各部份分别选取了M4前几个型号的部分结构，前期主炮仍使用75mm口径火炮，但坦克改用了具有500匹马力、结构紧凑的福特GAA汽油发动机，使其最高车速提高到41.6KM/h, 最大行程达到208km。</p><p>至1943年9月，一共生产了近4000辆M4A3、4500多辆装备76mm火炮的M4A3（76）W和3000多辆装备了105主炮的M4A3（105）中型坦克。</p><p>该型坦克开始服役时间是1942年6月，主要分配给美军自用，是美军M4”谢尔曼“系列坦克中服役时间最长，改进最大，应用最广的主力坦克型号。</p>","caption":""},{"image":"{{text}}M4A4“谢尔曼Ⅴ”中型坦克{{image}}imgs/us/army/us_army_tankm4_51.jpg{{text}}1944年，英军第2爱尔兰装甲护卫队的一辆M4A4“谢尔曼Ⅴ”中型坦克；显然该型坦克车身较同系列其它型号长。注意：该型坦克炮塔后部都会带有一个储物箱。{{image}}imgs/us/army/us_army_tankm4_52.jpg{{text}}M4A4中型坦克的车体前部由三部分拼接而成，并带有侧面裙板防护。{{image}}imgs/us/army/us_army_tankm4_53.jpg","description":"<h6>M4A4“谢尔曼Ⅴ”中型坦克</h6><p>该型车坦克为焊接车体，车体前部份由三块钢板拼接，由于坦克采370匹马力30缸汽油发动机，发动机舱加长了接近30cm，因此车体显得较长。坦克的主炮为75mm口径火炮，前期生产的炮塔采用小防盾，但后期则改为大防盾。</p><p>至1943年9月，该型坦克一共生产了7490多辆。大部分根据租借法案提供给了盟军部队，其中英国接收的数量最多。</p><p>该型坦克开始服役时间是1942年7月。</p>","caption":""},{"image":"{{text}}M4A5中型坦克{{image}}imgs/us/army/us_army_tankm4_61.jpg","description":"<h6>M4A5中型坦克</h6><p>M4A5中型坦克是美国转产加拿大的“公羊”坦克，由美国火车头制造厂下属的加拿大公司按M4图纸生产，并作了一系列改造，1942年2月被美国军械局正式命名为 M4A5。截至1943年夏天一共生产了1800多辆（“公羊”Ⅱ型），该型坦克装备加拿大军队后并未参加实战，多为训练用。注意：图中坦克的火炮为英制40mm2磅炮。</p>","caption":""},{"image":"{{text}}M4A6中型坦克{{image}}imgs/us/army/us_army_tankm4_62.jpg{{image}}imgs/us/army/us_army_tankm4_63.jpg","description":"<h6>M4A6中型坦克</h6><p>M4A6中型坦克与后期生产的M4A4有很多类同处，只是车体前部从M4A4的三件拼接改变为整个部件铸造，并改用了输出功率为450匹马力的D200A油喷多燃料发动机。 M4A6中型坦克从1943年10月开始投产，至1944年2月只生产了75辆就停产了。后来该批坦克留在美国本土作训练用。</p>","caption":""},{"image":"{{text}}M4A3E2坦克{{image}}imgs/us/army/us_army_tankm4_64.jpg","description":"<h6>M4A3E2坦克</h6><p>1944初，为了配合美军在西欧的反攻，美国在M4A3的坦克基础上又研制了一款重装甲突击坦克M4A3E2，以支援步兵作战。该型坦克最大特点是装甲厚重，车体正面装甲为102mm，侧面装甲为76mm，炮塔四面装甲厚达152mm，炮盾厚178mm，加装重型装甲后整车重38t，最高车速也降至35km/h；1944年5-7月，已生产的250多辆M4A3E2坦克全部被派往西欧战场，虽然该型坦克仍用75mm火炮，火力不算很强，但其披挂的重装甲却能抵受德军“虎”式坦克炮的攻击，战场表现令美军感到满意。</p>","caption":""},{"image":"{{text}}M4A3E8坦克{{image}}imgs/us/army/us_army_tankm4_65.jpg","description":"<h6>M4A3E8坦克</h6><p>该款M4A3改进型坦克的悬挂系统采用两组双排转动轮和新型宽履带的HVSS装置，使坦克的机动性、耐用性都有显著提高，也更能适应更差的路况，更为火炮的行进射击提供了稳定的平台（后期生产的M4坦克都改用了HVSS装置）。该型坦克在1944年生产了约500台，也在欧洲战场投入了实战。注意：图中坦克悬挂系统与M4系列其它坦克的不同处。</p>","caption":""},{"image":"{{text}}M4“谢尔曼”工程坦克{{image}}imgs/us/army/us_army_tankm4_66.jpg","description":"<h6>M4“谢尔曼”工程坦克</h6><p>该坦克可作战斗用，也可作推土或推移障碍物等工作用。</p>","caption":""},{"image":"{{text}}M4“谢尔曼”扫雷坦克{{image}}imgs/us/army/us_army_tankm4_67.jpg","description":"<h6>M4“谢尔曼”扫雷坦克</h6><p>在扫雷的同时，该坦克可以同时开炮射击。图中坦克隶属英军第22龙骑兵团。</p>","caption":""}],"part2title":"战场上的M4系列坦克","part2description":"<p>M4“谢尔曼”中型坦克首次实战是在1942年的非洲阿拉曼战役中，当年10月，装备250多辆M4A1中型坦克的英军第1装甲师第2装甲旅前锋部队与德军第15装甲师的3号和4号坦克相遇，战斗中互有损伤，但在整个战役中， M4“谢尔曼”凭着75mm火炮准确快速的射击取得了相对优势，在战斗中发挥了重要作用，迫使德军败退至突尼斯。而美军的谢尔曼坦克首次实战也是在非洲战场，在1943年2月，装备M4A1中型坦克的美军第1装甲师的1个坦克营，在“春风”行动的进军中遭德军埋伏，被击毁了44辆谢尔曼坦克；后美军调集了58辆谢尔曼坦克进行反攻，解救了被围困的美军，但也损失了包括谢尔曼坦克在内的各型坦克98辆。</p><p>盟军在法国诺曼第登陆后，盟军装备了76mm火炮的M4A2、M4A3、M4A4等中型坦克在德军的“豹”式和“虎”式坦克面前仍是一筹莫展，但多次交锋和严重战损使盟军坦克手积累了经验，通过迂回战术与瞄准对手装甲薄弱处给予攻击，并通过用沙袋、木桩围蔽坦克车体来加强防护，也取得了一定的对抗能力，后美军得到了改装了105mm的M4系列坦克和安装了重型装甲的M4A3E2及E8坦克，火力和防护得到大大加强，再加上此时盟军已源源不断地得到大量M4系列坦克的补充，在数量上完全压倒了德军的坦克，由此在欧洲战场上盟军已占尽优势。</p><p>1943年底开始，苏军也从美国手中接收了数千辆M4A2中型坦克，从1944对德军的反攻的开始至1945年攻克德国首都柏林，在二年的战斗中，这些坦克也为苏军创下了不少战绩。</p><p>而在东南亚战场上，美军、英军与中国远征军也用M4A3、M4A4中型坦克与日军作战，日军的“97改”坦克根本就不是M4的对手，1945年3月的缅甸战场，在进攻曼德勒战斗中，M4A4中型坦克几乎全歼日军在缅甸唯一的第14战车联队。</p>","part2content":[{"image":"imgs/us/army/us_army_tankm4_71.jpg","description":"1944年2月6日，美军第1装甲师的1个M4A1车组在卡西诺前线的战斗间隙中整理坦克上的机枪，在1月底这个师在Mignano附近分成二个部分，一部分在南部前线支援第2集团军，另一则前往安齐奥滩头支援第6集团军。","caption":""},{"image":"imgs/us/army/us_army_tankm4_72.jpg","description":"1944年4月，在意大利战场，一辆安装了105mm火炮的美军M4（105）坦克正带领一队M4坦克行进在村庄的葡萄园中。","caption":""},{"image":"imgs/us/army/us_army_tankm4_73.jpg","description":"1944年5月19日，进攻安齐奥的战斗中，当卡西诺镇被攻占后，一辆M4A1坦克在行进中。这辆坦克属于早期生产型，但也采用了双层装甲进行防护升级。","caption":""},{"image":"imgs/us/army/us_army_tankm4_74.jpg","description":"1944年8月，美军第1装甲师第13坦克营A连2排在意大利洛伦扎纳附近地区测试刚接收的配备长身管76mm火炮的M4A3（76）W中型坦克。","caption":""},{"image":"imgs/us/army/us_army_tankm4_75.jpg","description":"1943年8月，西西里战场，一辆美军的M4坦克正在一辆被击毁的德军4号坦克旁边驶过。","caption":""},{"image":"imgs/us/army/us_army_tankm4_76.jpg","description":"1944年10月，意大利战场，隶属美军755独立坦克营的多辆M4坦克停在山坡上正在向敌方阵地射击，因战场山脉众多，坦克不宜行进，故M4作支援步兵的火炮用。","caption":""},{"image":"imgs/us/army/us_army_tankm4_77.jpg","description":"1944年欧洲战场一辆掉进泥坑中的美军的M4坦克。","caption":""},{"image":"imgs/us/army/us_army_tankm4_78.jpg","description":"1944年8月16日，一辆后期生产的M4A1（前）和一辆安装了105火炮的M4（105）（后）中型坦克在行进，这两辆坦克都是美军装甲部队在诺曼底战场早期战斗的主力装备。前面一辆M4A1安装了树篱切割器，专门用作切割诺曼第布列塔尼地区的矮小灌木以开辟道路。","caption":""},{"image":"imgs/us/army/us_army_tankm4_79.jpg","description":"1944年，隶属自由法国军第2装甲师的一辆M4A2中型坦克在法国沿海登陆，重回法国作战。","caption":""},{"image":"imgs/us/army/us_army_tankm4_80.jpg","description":"在意大利战场，一辆美军的M4A2坦克正在渡河，在坦克后部发动机进风口处安装有专门的涉水装置以防止河水灌入。","caption":""},{"image":"imgs/us/army/us_army_tankm4_81.jpg","description":"1944年秋，一支装备M4A2（76）坦克的苏军部队正在向波兰战场进发。","caption":""},{"image":"imgs/us/army/us_army_tankm4_82.jpg","description":"1945年2月29日，在法国战场，美军第36师142步兵团C连正在第14装甲师的一辆M4A3（76）带领下在雪地中行进。他们的任务是对德军在阿尔萨斯发起的北风行动进行反击并收复失地。当时 他们正在支援第36师进攻Gabsheim桥头堡。","caption":""},{"image":"imgs/us/army/us_army_tankm4_83.jpg","description":"在1945年3月21日的突击进攻中，隶属巴顿第3军第11装甲师第41坦克营的一辆M4A3（76）W HVSS中型坦克首先进抵德国莱茵河。","caption":""},{"image":"imgs/us/army/us_army_tankm4_84.jpg","description":"1945年3月14日，美军第14装甲师的M4A3（76）W HVSS中型坦克（已换装HVSS悬挂装置，以下同。）正在德国Ohlungen地区附近进行无线电测试。坦克车体和炮塔周边已用沙袋围住以增强防护，这种做法在美军装甲部队（如第7军和巴顿的第3军）普遍存在，但军方高层似乎并不主张。","caption":""},{"image":"imgs/us/army/us_army_tankm4_85.jpg","description":"在1945年3月23日，行进在德国Silz地区附近的美军第14装甲师的一辆M4A1（76）W中型坦克，此地区刚经历了一场激烈的战斗，坦克周围都是废墟和德军败退时扔弃的装备。这辆坦克也使用了沙袋加强防护。","caption":""},{"image":"imgs/us/army/us_army_tankm4_86.jpg","description":"1945年4月5日，一辆美军第771坦克营的M4A1（76）坦克正穿过德国Muenster市区的废墟前往支援第17空降师，与部署在诺曼第地区的同型坦克不同的是：这辆坦克的炮塔上有1 个椭圆形的出入舱口，另外装甲覆盖了进气口。","caption":""},{"image":"imgs/us/army/us_army_tankm4_87.jpg","description":"在1945年，一辆苏军的M4中型坦克正在进入德国首都柏林市区街道，路边的居民楼上挂着一面白旗，证明此时柏林已被苏军攻占。","caption":""},{"image":"imgs/us/army/us_army_tankm4_88.jpg","description":"德军中的M4中型坦克：图中为1943年2月北非德军第21装甲师缴获的一辆M4A1坦克，坦克车体前部已披上一面德军旗帜作识别。这是德军最早缴获的谢尔曼坦克。在北非和欧洲战场上，德军先后缴获了盟军不少M4各型坦克，若坦克完好则会立即编入德军装甲部队，谢尔曼坦克在德军中的型号是“Pzkpfw M4 748(a)”。","caption":""},{"image":"imgs/us/army/us_army_tankm4_89.jpg","description":"1945年初，菲律宾战场，美军一辆M4A3中型坦克正在一辆被击毁的日军97式坦克旁边经过。在太平洋战场上，日军的97式坦克根本就无法与M4坦克对抗。","caption":""},{"image":"imgs/us/army/us_army_tankm4_90.jpg","description":"在1945年初，在缅甸战场，一队中国远征军的M4A4中型坦克正在丛林路上进发。","caption":""},{"image":"imgs/us/army/us_army_tankm4_91.jpg","description":"1945年3月，在中缅战场，中国远征军的一辆M4A4中型坦克正在行进中，该辆坦克车体上涂有”突击“二字，炮塔前还画上了狰狞的虎头。","caption":""},{"image":"imgs/us/army/us_army_tankm4_92.jpg","description":"1944年12月，缅甸南部战场，隶属英印军第5”国王爱德华七世”枪骑兵团B中队的M4A4中型坦克群正向日军展开攻击。","caption":""},{"image":"imgs/us/army/us_army_tankm4_93.jpg","description":"1945年8月，隶属苏联后贝加尔方面军第9机械化集团军第6坦克军的一辆M4A2（76）W谢尔曼中型坦克进入中国东北作战，受到中国民众的欢迎。","caption":""}]}')}});